namespace ghidra.app.plugin.core.symboltree.actions;










using docking;
using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree.support;
using ghidra.app.plugin.core.symboltree;
using ghidra.app.plugin.core.symboltree.nodes;
using resources;

public class PasteAction : SymbolTreeContextAction {

	private static Icon PASTE_ICON = Icons.PASTE_ICON;

	public PasteAction(SymbolTreePlugin plugin, SymbolTreeProvider provider) : base("Paste Symbols", plugin.getName())
    {
		setPopupMenuData(new MenuData(new string[] { "Paste" }, PASTE_ICON, "cut/paste"));
		setKeyBindingData(
			new KeyBindingData(
				KeyStroke.getKeyStroke(KeyEvent.VK_V, DockingUtils.CONTROL_KEY_MODIFIER_MASK),
				KeyBindingPrecedence.ActionMapLevel));
	}

	/* @Override */
	public bool isAddToPopup(SymbolTreeActionContext context) {
		TreePath[] selectionPaths = context.getSelectedSymbolTreePaths();
		return selectionPaths.length > 0;
	}

	/* @Override */
	public bool isEnabledForContext(SymbolTreeActionContext context) {

		TreePath[] selectionPaths = context.getSelectedSymbolTreePaths();
		if (selectionPaths.length != 1) {
			return false;
		}

		object pathComponent = selectionPaths[0].getLastPathComponent();
		if (!(pathComponent is SymbolTreeNode)) {
			return false;
		}

		SymbolTreeNode node = (SymbolTreeNode) pathComponent;
		Clipboard clipboard = context.getSymbolTreeProvider().getClipboard();
		Transferable transferable = clipboard.getContents(this);
		if (transferable == null) {
			return false;
		}
		return node.supportsDataFlavors(transferable.getTransferDataFlavors());
	}

	/* @Override */
	public void actionPerformed(SymbolTreeActionContext context) {
		TreePath path = context.getSelectedPath();
		if (path == null) {
			return;
		}
		GTreeNode destinationNode = (GTreeNode) path.getLastPathComponent();
		Clipboard clipboard = context.getSymbolTreeProvider().getClipboard();
		Transferable transferable = clipboard.getContents(this);
		if (transferable == null) {
			return;
		}

		GTreeDragNDropHandler dragNDropHandler = context.getSymbolTree().getDragNDropHandler();
		dragNDropHandler.drop(destinationNode, transferable, DnDConstants.ACTION_MOVE);
		clipboard.setContents(null, null);
	}

}
